L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "Midnight Lily 的輸出版本。專注、簡潔的配置，讓你的循環與冷卻時間始終位於正中央。"
