L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "當你變身、潛行或切換姿態時，讓快捷列 1 保持在目前的頁面，而不是切換到該姿態的快捷列。\n\n快捷鍵會跟著快捷列顯示的內容走，因此按鍵永遠施放你看到的圖示。啟用此選項時，快捷列 1 的按住重複施放會關閉。"
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "使用飛龍騎術時，讓快捷列 1 保持在目前的頁面，而不是切換到飛龍騎術快捷列。\n\n你的飛龍騎術技能位於該快捷列，因此啟用前請先將它們移到其他快捷列。啟用此選項時，快捷列 1 的按住重複施放會關閉。"
