L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "依不同的堆疊層數以不同顏色顯示進度條，並以目前達到的最高層數為準。"
L["Comma separated stack counts to put a tick mark at. Type all to mark every stack."] = "請輸入要顯示刻度標記的堆疊層數（以逗號分隔）。輸入「all」即可標記所有層數。"
