L["Edit Mode Needs a Manual Fix"]  = "編輯模式需要手動修正"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI 無法將此變更儲存至你的編輯模式版面，因此需要手動設定。設定期間須停用冷卻管理器，因為它會隱藏暴雪的冷卻檢視器，而隱藏的檢視器無法在編輯模式中選取。\n\n"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI 無法將這項變更存入你的編輯模式配置，因此必須手動設定。設定期間必須先關閉冷卻管理器，因為它會隱藏暴雪的技能監控，而被隱藏的項目無法在編輯模式中選取。\n\n1. 停用 EllesmereUI 冷卻管理器（下方按鈕）。\n2. 從遊戲選單開啟編輯模式。\n3. 選取每一個技能監控項目，並將「能見度」設為「隨時可見」。\n4. 在「追蹤的增益效果」與「追蹤的量條」上勾選「未啟用時隱藏」。\n5. 儲存配置並離開編輯模式。\n6. 重新啟用 EllesmereUI 冷卻管理器。"
L["Extra horizontal shift stacked on top of this bar's normal position. Unlock mode shows the base position; the offset re-applies when you exit."] = "在此條的正常位置之上額外疊加的水平位移。解鎖模式會顯示基準位置；離開後偏移會重新套用。"
L["Extra vertical shift stacked on top of this bar's normal position. Unlock mode shows the base position; the offset re-applies when you exit."] = "在此條的正常位置之上額外疊加的垂直位移。解鎖模式會顯示基準位置；離開後偏移會重新套用。"
L["Fills the bar as the cooldown recovers instead of draining it as the cooldown runs down."] = "隨著冷卻恢復而逐漸填滿計量條，而非隨著冷卻倒數而消耗減少。"
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "當法術沒有剩餘充能時隱藏充能數字，而不是顯示 0。一旦充能恢復，數字就會重新出現。"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "在非戰鬥狀態下完全隱藏此條，即使追蹤的增益效果／冷卻仍在作用中。"
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "隱藏此列的圖示圖案、冷卻轉圈效果、充能邊緣與冷卻文字，僅保留充能數或堆疊層數。"
