L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "當剩餘時間低於齒輪圖示設定的「剩餘秒數」門檻時，在預設與自訂法術/物品 ID 上顯示至小數點後 1 位的倒數。這適用於冷卻/功能列上的啟用狀態，以及增益列上的 Buff 持續時間（兩者皆由系統底層直接計算，因此剩餘時間極為精準）。"
