L["Show the charge and stack counters on this bar's icons."] = "在此列的圖示上顯示充能數與堆疊層數。"
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected."] = "在追蹤的物品上顯示製作品質等級，與快捷列上的品質圖示一致。沒有製作品質的物品不受影響。"
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "在你當前目標的名條上顯示 焦點打斷 列，而非專注目標的名條。"
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "在此快捷列的每個冷卻上顯示旋轉冷卻邊緣動畫，而不僅限於充能恢復期間。「隱藏充能邊緣」選項對個別充能法術仍會優先覆蓋此設定。"
