L["Sync cleared -- only one spec was selected. Tick at least two specs (including other characters' specs) to sync between them."] = "同步已清除：只選取了一個專精。請至少勾選兩個專精（可包含其他角色的專精）才能在它們之間同步。"
L["Sync Generic CDs/Buffs"]        = "同步一般冷卻／增益效果"
L["Sync Racials, Pots & Trinkets"] = "同步種族技能、藥水與飾品"
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "正在跨 %d 個專精同步一般冷卻／增益效果。圖示順序不會同步，每個專精各自保留自己的排列。"
L["Talent gating is only available while playing this spec's class"] = "天賦限制僅在遊玩此專精的職業時可用"
L["Text Wrap"]                     = "文字換行"
L["The single stack threshold is off while Multiple Thresholds is on."] = "啟用「多重臨界值」時，單一層數臨界值將會停用。"
L["Thickness"]                     = "厚度"
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "調整指派至此列按鈕的像素發光厚度。您可在預覽中右鍵點擊圖示來設定發光效果。"
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "套用於此條增益效果圖示的「像素發光」粗細。"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "此條在選項中設定了額外條偏移（X %1$s，Y %2$s）。解鎖模式會顯示基準位置；離開後偏移會重新套用。"
L["This bar will always be attached to your focus target's nameplate"] = "此列將永遠附著於你的專注目標名條上"
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "這無法變更使用者在暴雪冷卻管理器中所追蹤的法術。\n建議你在這裡所選的任何專精，也一併分享你的暴雪冷卻管理器配置。"
L["This is the spec you're syncing from -- it's always included."] = "這是你要同步的來源專精，一律包含在內。"
L["This option is not available for custom shaped icons"] = "此選項不適用於自訂形狀圖示"
L["This option is only available for abilities with multiple charges"] = "此選項僅適用於具有多次充能的技能"
L["This option requires a cooldown-tracking bar"] = "此選項需要冷卻追蹤條"
L["This option requires a Duration Text position other than None"] = "此選項需要持續時間文字位置非「無」"
L["This option requires a gradient to be set"] = "此選項需要已設定漸層"
L["This option requires a Name Text position other than None"] = "此選項需要名稱文字位置非「無」"
L["This option requires a non-custom button shape"] = "此選項需要非自訂的按鈕形狀"
L["This option requires a non-custom shape to be selected"] = "此選項需要選擇非自訂的形狀"
L["This option requires a Stacks Text position other than None"] = "此選項需要層數文字位置非「無」"
L["This option requires exactly 2 rows"] = "此選項需要恰好 2 列"
L["This option requires Fill Color to be set to Custom"] = "此選項需要填充顏色設為自訂"
L["This option requires Pixel Glow to be the selected glow type"] = "此選項需選擇像素發光作為發光類型"
L["This replaces %d existing value(s) for this setting across your specs."] = "這將取代各專精中現有的 %d 個此設定值。"
L["This replaces %d existing value(s) for this setting on this bar."] = "這將取代此進度條上現有的 %d 個此設定值。"
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "此設定目前生效的「套用至進度條（所有專精）」設定值將被取代。"
L["This setting's active Apply to Bar value will be replaced."] = "此設定目前生效的「套用至進度條」設定值將被取代。"
L["This spec doesn't have this spell."] = "此專精沒有這個法術。"
