L["This will change the color of your bar if you have more than your chosen number of stacks"] = "當層數超過你設定的數量時，此設定會改變長條顏色"
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "這會停用 EllesmereUI 追蹤列，改為顯示暴雪預設的追蹤列。"
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "若你未設定專注目標，這會在傳奇+中於施法者／小首領怪物下方顯示「FOCUS」字樣。無中斷技能的專精會停用此功能。"
L["This will keep appearing each login until the layout is correct."] = "在配置正確之前，這則訊息每次登入都會出現。"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "這會將目前專精所有預設條的法術指派重設為暴雪原生冷卻管理器的配置。你自行加入的法術（預設組合、自訂 ID 與種族技能）會保留。要繼續嗎？"
