L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "當目前專精在此群組中沒有任何條時，錨定於該群組的元素會留在原位，並向上或向下位移一個條的高度（可用齒輪中的「額外垂直偏移」微調），以填補其空缺。"
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "當背包內缺乏某種戰鬥藥水時，其圖示會切換為追蹤你擁有的下一種藥水。"
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "當你按下技能的按鍵綁定時，即使該技能正在冷卻中，也會在此動作條的圖示上顯示動作按鈕的「壓下」效果。"
