L["Health Bar Width"]              = "生命條寬度"
L["Hide Enemy Name While Casting"] = "施法時隱藏敵人名稱"
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "在非戰鬥狀態下隱藏敵方名條；一進入戰鬥便立即恢復顯示。此選項操作的是與「顯示敵方名條」快捷鍵相同的遊戲設定。"
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "隱藏友方玩家的血條，僅顯示其名稱。\n\n需要在暴雪名條設定中停用「簡化友方名條」（Esc > 選項 > 名條）。"
L["Hide the 1-pixel border around the cast bar spell icon."] = "隱藏施法條法術圖示周圍的 1 像素邊框。"
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "當該名條的施法條顯示時，隱藏敵人的名稱文字。"
