L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "圖示上下各要裁掉多少，以單邊百分比計算。10% 即是經典的裁切外觀。"
L["Icon on Right"]                 = "圖示置右"
