L["Increases the cast bar height on your focus target's nameplate. 100% = normal height."] = "增加你專注目標名條上的施法條高度。100% = 正常高度。"
L["Increases the clickable hitbox height of enemy nameplates. 100% = matches bar height. Increase to make nameplates easier to click."] = "增加敵方名條的點擊判定區高度。100% = 與血條高度相同。調高可讓名條更容易被點擊。"
