L["Make Friendly Nameplates Name Only"] = "友方名條僅顯示名稱"
L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "讓友方玩家與 NPC 名條可點擊穿透，使其名稱不再阻擋滑鼠，也不會意外選取友方目標。\n\n當友方名稱妨礙你點擊世界或其後方的敵方名條時，可使用此選項。"
L["Make Icon Part of the Bar"]     = "讓圖示成為條的一部分"
L["Make the spell icon a large square the combined height of the health bar plus the cast bar, flush with the top of the health bar and the bottom of the cast bar."] = "將法術圖示設為血條與施法條總高度的大型方塊，並與血條頂端及施法條底端完全齊平。"
L["Max Debuffs"]                   = "最大減益效果數"
L["Maximum number of debuff icons shown on enemy nameplates."] = "敵方名條上顯示的減益效果圖示上限。"
L["Maximum width the text can fill before it truncates, as a percentage of the bar."] = "文字截斷前可填滿的最大寬度，以列寬的百分比表示。"
L["Medium Stripes"]                = "中等條紋"
L["MINE"]                          = "自己"
