L["NAMEPLATE AURA FILTERS"]        = "名條光環篩選器"
L["NAMEPLATE SPACING"]             = "名條間距"
L["Nameplates opacity for units that are out of line of sight. 0 = fully transparent, 1 = fully opaque."] = "視線受阻單位的名條不透明度。0 = 完全透明，1 = 完全不透明。"
