L["NPC Bar & Name Color"]          = "NPC 血條與名稱顏色"
L["Nudge the cast bar up or down from its default spot under the health bar."] = "將施法條從其預設位置（血條下方）向上或向下微調。"
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "在開放世界的任務怪物身上，將任務圖示替換為目標進度（例如：擊殺任務顯示 0/6、百分比目標顯示 50%）。"
L["Only Dispellable"]              = "僅可驅散"
L["Opacity used for enemy nameplates outside the selected attack range."] = "超出所選攻擊距離的敵方名條所使用的不透明度。"
L["OTHER COLORS"]                  = "其他顏色"
L["Out of Combat Color"]           = "非戰鬥顏色"
L["Override Boss colors"]          = "覆蓋首領顏色"
