L["Pandemic Glow Style"]           = "刷新時機發光樣式"
L["Pixel-perfect border around the cast bar. Set to 0 for no border."] = "施法條周圍的像素級邊框。設為 0 則無邊框。"
L["Place the cast bar spell icon on the right side of the bars instead of the left."] = "將施法條的法術圖示放置於條的右側而非左側。"
L["Player Title"]                  = "玩家稱號"
L["Position Settings"]             = "位置設定"
L["Pulses a red glow on enemy nameplates below 30% health."] = "當敵人生命值低於 30% 時，其名條會脈動紅色光芒。"
