L["Scale Nameplate On Cast"]       = "施法時縮放名條"
L["Scale Target Nameplate"]        = "縮放目標名條"
L["Scales enemy nameplates while they are casting. 100% = no change."] = "敵人施法時縮放其名條。100% = 不變。"
L["Scales your current target's nameplate. 100% = no change."] = "縮放你目前目標的名條。100% = 不變。"
