L["Show <> Around Guild"]          = "在公會名稱外加上 <>"
L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "當敵人正在施放暴雪標記為重要的法術時，在施法條上顯示發光效果。"
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "當敵人的施法無法中斷時，於施法條上顯示護盾圖示。"
L["Show All Enemy Buffs"]          = "顯示所有敵方增益效果"
L["Show All Your Player Debuffs"]  = "顯示你所有的玩家減益效果"
L["Show Border"]                   = "顯示邊框"
L["Show Class Resource"]           = "顯示職業資源"
L["Show Enemy Pet Nameplates"]     = "顯示敵方寵物名條"
L["Show EUI Friendly Player Nameplates"] = "顯示 EUI 友方玩家名條"
L["Show Friendly NPC Nameplates"]  = "顯示友方 NPC 名條"
L["Show Hash Line on Target at Percent"] = "在目標的指定百分比處顯示標記線"
L["Show Health Percent"]           = "顯示生命百分比"
L["Show In Instances"]             = "在副本中顯示"
L["Show Interrupted Flash Effect"] = "顯示中斷閃爍效果"
L["Show NPC Titles"]               = "顯示 NPC 稱號"
L["Show Shield Icon"]              = "顯示護盾圖示"
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "在控場圖示欄位中顯示成功的斷法封鎖狀態。\n\n受限於插件限制，所有職業顯示的斷法時間皆統一為 4 秒，因此並非 100% 準確。"
L["Show the bright spark at the leading edge of the cast bar fill."] = "在施法條填充的前緣顯示明亮的火花。"
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "在友方名條上，將玩家稱號與名字顯示於同一行，及／或在其下方另起一行顯示公會名稱。"
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "在友方名條上，以較小的一行在玩家名字下方顯示其稱號或公會。"
L["Show/Hide Hitbox Overlay"]      = "顯示／隱藏碰撞框疊層"
L["Show/Hide on Preview"]          = "在預覽上顯示／隱藏"
L["Showing this aura from any caster; click for your casts only."] = "目前顯示任何施法者的此光環；點擊以改為僅顯示你自己施放的。"
L["Showing this aura from your casts only; click for any caster."] = "目前僅顯示你自己施放的此光環；點擊以改為顯示任何施法者的。"
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "在敵方名條上只顯示單一個「血魄瘟疫」減益效果，而非每份複製各顯示一個（武器複製來自沸血術）。"
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "當團隊中的其他坦克擁有仇恨時，將其名條顯示為特殊顏色。"
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "當您未擁有仇恨時，將非施法者或小首領怪物的名條顯示為特殊顏色。"
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "當您已擁有仇恨時，將非施法者或小首領怪物的名條顯示為特殊顏色。"
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "在敵方名字文字的正前方顯示目標標記。使用獨立的大小設定，且不佔用核心位置預設的團隊標記欄位。"
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "於敵人施法期間，顯示您的中斷技能何時冷卻就緒。「刻度」會在施法條上標記精確位置；「刻度 + 計量條」則會額外將中斷技能可用的時間區段著色。"
L["Simple Arrows"]                 = "簡單箭頭"
