L["Stacking Nameplates"]           = "堆疊名條"
L["Stripes"]                       = "條紋"
L["Subtitle Text Settings"]        = "副標題文字設定"
L["Subtitle Text Size"]            = "副標題文字大小"
L["Tank Threat"]                   = "坦克仇恨"
L["Tank: Show Special \"Has Aggro\" Color"] = "坦克：顯示特殊「已取得仇恨」顏色"
L["Tank: Show Special \"Off-Tank\" Color"] = "坦克：顯示特殊「副坦克」顏色"
L["Target"]                        = "目標"
L["TARGET AND FOCUS EFFECTS"]      = "目標與焦點特效"
L["Target Arrows"]                 = "目標箭頭"
L["Target Effect"]                 = "目標效果"
L["Target Glow Style"]             = "目標發光樣式"
L["Target Highlight"]              = "目標發光"
L["Target Preview"]                = "目標預覽"
L["Target Texture"]                = "目標材質"
L["TARGET, FOCUS & HOVER EFFECTS"] = "目標、專注目標與滑鼠懸停效果"
L["This bar will always be attached to your current target's nameplate"] = "此列將永遠附加至你目前目標的名條"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "此功能會對每個可見的敵方名條持續執行距離檢查。它是 EllesmereUI 中較耗效能的功能之一，在人多的區域可能明顯增加 CPU 使用量。"
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "讓施法條的寬度包含圖示，而不是把圖示放在施法條寬度的左側。"
L["This option is only used by the Basic border."] = "此選項僅適用於基本邊框。"
L["This option requires a text to be assigned"] = "此選項需指派一段文字"
L["This option requires an aura or indicator to be assigned"] = "此選項需指派光環或指示器"
L["This option requires Subtitle Text to include the Guild Name"] = "此選項需要「副標題文字」包含公會名稱才能生效"
L["THREAT COLORS (INSTANCES ONLY)"] = "仇恨顏色（僅限副本）"
L["Tick"]                          = "刻度"
L["Tick + Bar"]                    = "刻度 + 計量條"
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "當敵人施放遊戲標記為重要的法術時，以「重要」顏色為施法條上色。此設定會覆蓋「可中斷施法」顏色；但你的中斷技能處於冷卻中時仍優先顯示。"
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "以生命條目前的顏色為材質上色，而非使用自訂的覆蓋層顏色。"
L["Tiny Stripes"]                  = "極小條紋"
L["Title & Guild"]                 = "稱號與公會"
L["Toggle visibility of enemy pet nameplates."] = "切換敵方寵物名條的可見性。"
L["Top Left"]                      = "左上"
L["Top Right"]                     = "右上"
L["Top Text"]                      = "頂部文字"
L["Uninterruptible Cast"]          = "無法中斷的施法"
L["Use Target Border Color"]       = "使用目標邊框顏色"
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "使用懸停效果的顏色與不透明度。設定為「無」則使用一般平面的懸停發光。"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "停用此功能時，EUI 將會把友方玩家名條的完整控制權交還給暴雪。請使用暴雪內建的名條設定（Esc > 選項 > 名條）來進行調整。"
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "決定名條上顯示哪些敵方增益效果。「重要」顯示暴雪為敵方名條標記的增益效果，以及所有可驅散的增益效果；「僅可驅散」僅顯示可被驅散、淨化或安撫的增益效果。只要設定了驅散發光樣式，所有顯示中可驅散的增益效果都會發光。"
L["White"]                         = "白色"
L["Wide Stripes"]                  = "寬條紋"
L["Widens the clickable hitbox of enemy nameplates. 100% = matches bar width. Increase to make nameplates easier to click."] = "加寬敵方名條的可點擊範圍。設定為 100% 時與血條同寬；調高此數值可使名條更容易被點選。"
L["Width %"]                       = "寬度 %"
L["Winged"]                        = "翼狀"
L["Wrap"]                          = "換行"
L["Wrap Around Castbar"]           = "環繞施法條"
L["X"]                             = "X"
L["Y"]                             = "Y"
L["Your focus target's nameplate never fades with the non-target opacity."] = "你的專注目標名條永遠不會套用非目標的不透明度而淡化。"

-- == Unit Frames ==========================================================
L["(Applies to All Units)"]        = "（套用至所有單位）"
