L["3D Zoom"]                       = "3D 縮放"
L["Above Absorb Bar"]              = "吸收條上方"
L["Above Frame Left"]              = "框架上方靠左"
L["Above Frame Right"]             = "框架上方靠右"
L["Above Health Bar"]              = "生命條上方"
L["Absorb Amount"]                 = "吸收量"
L["Absorb Short (230k)"]           = "吸收量縮寫 (230k)"
L["Activate Boss Preview"]         = "啟動首領預覽"
L["Add Buff Bar"]                  = "新增增益效果列"
L["Add Debuff Bar"]                = "新增減益效果列"
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "當你以非坦克身分搶到或持有仇恨時，為你的玩家框架加上暗影邊框。僅在地城、團隊本與探究中作用。"
L["Alignment"]                     = "對齊"
L["All Buffs"]                     = "所有增益效果"
L["All Buffs or Has Duration"]     = "所有增益效果或帶有持續時間"
L["All Buffs or Has Duration is selected, so every buff already shows. Use the red Hide box to exclude these instead."] = "已選擇「所有增益效果或帶有持續時間」，因此所有增益效果都已顯示。請改用紅色的「隱藏」方框來排除這些項目。"
L["Also show the badge in dungeons and raids, where most enemies are elite."] = "在地城與團隊副本中也顯示此標示，該處大多數敵人都是精英。"
