L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "依剩餘生命值為血條上色，而不是使用單一固定顏色。「經典」從滿血時的綠色，經黃色漸變到沒血時的紅色。「自訂顏色」會在此列的三個色塊之間漸層——分別代表滿血 (100%)、半血 (50%) 與沒血 (0%)。「依職業自動變色」在滿血時顯示職業顏色，並隨著單位受到傷害逐漸融入 50% 與 0% 的顏色。「關閉」則交由「填滿顏色」的固定色塊決定；無論選擇哪一種，下方的漸層仍會生效，並從此處決定的顏色開始延伸。"
