L["Overrides the border size from the main frames for this frame only. Border color and texture still follow the main frames."] = "僅針對此框架覆寫主框架的邊框大小。邊框顏色與材質仍沿用主框架。"
L["Overrides the Frame Strata set in the main frames for this frame only. Controls the order that overlapping frames display in; set higher to show above other frames."] = "僅在此框架覆蓋主框架所設定的框架層級。此功能用於控制重疊框架的顯示順序；設定值越高，顯示層級越上一層（會遮蓋其他框架）。"
