L["Show aura tooltips when hovering buff and debuff icons on all unit frames except boss frames."] = "滑鼠懸停於首領以外的所有單位框架增益與減益圖示時，顯示光環提示資訊。"
L["Show aura tooltips when hovering buff and debuff icons on boss frames."] = "滑鼠懸停於首領框架的增益與減益圖示時，顯示光環提示資訊。"
