L["Show Cast Bar"]                 = "顯示施法條"
L["Show Cast Icon"]                = "顯示施法圖示"
L["Show combat indicator preview"] = "顯示戰鬥指示器預覽"
L["Show Cooldown Text"]            = "顯示冷卻文字"
L["Show Decimal on Health Text"]   = "血量文字顯示小數點"
L["Show dispel overlay preview"]   = "顯示驅散覆蓋預覽"
L["Show Duration (Inside Cog)"]    = "顯示持續時間（齒輪內）"
L["Show duration and stack count text on buff and debuff icons."] = "在增益與減益效果圖示上顯示持續時間與層數文字。"
L["Show Ellipsis"]                 = "顯示省略符號"
L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "顯示所有帶有持續時間的增益效果（隱藏永久增益效果）。可用下方的「隱藏」欄移除特定篩選器。"
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "顯示所有具持續時間的增益效果（隱藏永久增益效果）。啟用時，下方勾選的篩選器會被隱藏，而不是加入。"
L["Show every buff. Use the Hide lane below to remove specific filters."] = "顯示所有增益效果。可用下方的「隱藏」欄移除特定篩選器。"
L["Show every buff. While this is on, checked filters below are hidden from the bar instead of added."] = "顯示所有增益效果。啟用時，下方勾選的篩選器會從此列中隱藏，而不是加入。"
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "顯示所有增益效果。啟用時，下方勾選的篩選器會從框架中隱藏，而不是加入。"
L["Show every debuff. While this is on, checked filters below are hidden from the bar instead of added."] = "顯示所有減益效果。啟用時，下方勾選的篩選器會從此列中隱藏，而不是加入。"
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "顯示所有減益效果。啟用時，下方勾選的篩選器會從框架中隱藏，而不是加入。"
L["Show heal absorb preview"]      = "顯示治療吸收預覽"
L["Show Highlight Border"]         = "顯示發光邊框"
L["Show in Instances"]             = "在副本中顯示"
L["Show Kick Ready Mid-Cast Bar"]  = "顯示施法中中斷就緒條"
