L["Show Nicknames"]                = "顯示暱稱"
L["Show on Boss Frames"]           = "在首領框架上顯示"
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "血量文字顯示一位小數點：例如血量值顯示 240.5k、血量百分比顯示 77.3%。能量文字不受影響。預設為關閉。"
L["Show player nicknames from supported addons instead of character names on your main frames."] = "在主框架上顯示支援插件提供的玩家暱稱，而非角色名稱。"
L["Show Portrait"]                 = "顯示頭像"
L["Show Raid Marker"]              = "顯示團隊標記"
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "在此框架上顯示主框架的懸停發光邊框。關閉此功能可讓此框架在滑鼠懸停時永不變色。若主框架的「懸停邊框」已關閉發光，則此設定無實質效果。"
L["Show the name of who the boss is casting on."] = "顯示首領正在對其施法的對象名稱。"
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "顯示吸收盾超過您受損血量並往回填滿當前血量的部分。關閉時，吸收盾僅會填滿血條的空白受損部分。"
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "只要擁有寵物就顯示寵物框架，忽略玩家框架的可見性設定。"
L["Show the unit's tooltip when hovering the frame itself."] = "滑鼠懸停框架本身時顯示該單位的提示資訊。"
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "在此列的最前方顯示武器油與附魔圖示。它們屬於武器附魔而非光環，因此不受上方選項影響——光環格線會向內位移以騰出空間，每一列的位移量都相同。"
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "在施法條上你的中斷技能冷卻結束時施法所在的位置，顯示一個白色小刻度標記。"
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "在你的中斷技能冷卻結束時、施法會進行到的位置顯示一個白色小刻記。"
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "顯示所有帶有可驅散類型（魔法、詛咒、疾病、毒性、流血）的減益效果，即使你無法解除該效果。"
L["Shows only auras with a dispel type you can dispel"] = "僅顯示你能驅散的驅散類型光環"
L["Shows only buffs that can be canceled"] = "僅顯示可以取消的增益效果"
L["Shows only buffs you can spellsteal or purge"] = "僅顯示你能法術竊取或淨魔的增益效果"
L["Shows only crowd-control auras"] = "僅顯示控場類光環"
L["Shows only debuffs applied by bosses"] = "僅顯示由首領施加的減益效果"
L["Shows only debuffs Blizzard flags as important"] = "僅顯示暴雪標記為重要的減益效果"
L["Shows only debuffs flagged for your role"] = "僅顯示標記給你角色職責的減益效果"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "僅顯示暴雪官方精選團隊框架清單中的減益效果。"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "僅顯示非由任何玩家或玩家寵物造成的減益效果（大多數 PvE 減益效果皆以此顯示，勾選「所有減益效果」時請勿勾選此項！）"
L["Shows only external defensive cooldowns cast on the unit"] = "僅顯示由他人施放在此單位上的外部防禦技能"
L["Shows only major defensive cooldowns"] = "僅顯示主要的防禦技能"
L["Shows only the Debuffs you apply"] = "僅顯示由你施加的減益效果"
L["Shows only the stricter in-combat subset of the raid set"] = "僅顯示團隊名單中條件更嚴格的戰鬥中子清單。"
L["Shows the debuff's dispel type icon (Magic, Curse, Disease, Poison, Bleed) on the bar."] = "在效果列上顯示該減益效果的驅散類型圖示（魔法、詛咒、疾病、毒性、流血）。"
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "在精英、稀有精英與稀有目標上顯示名條樣式的巨龍標示。"
