L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "當使用自訂團隊大小時，隱藏群組中的隊員不會被計入團隊規模分界點。例如：如果您隱藏了第 7 和第 8 隊，即便是一個滿員的 40 人團隊，框架也會以 24 人的規格呈現，而不會直接跳轉到 30 人級別的框架大小。此選項僅在您啟用了自訂團隊大小的情況下才會生效。"
