L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "僅在能量條隱藏時顯示資源文字——包括已停用、此專精被篩選排除、專精沒有能量，或被「有資源時就隱藏能量條」隱藏的情況。關閉：一律顯示文字。"
