L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "團隊控制面板，提供準備確認、開怪倒數與團隊標記。在團隊中，僅在你是隊長或助理時才會顯示，因為沒有這個身分它的按鈕都無法使用；在小隊中則一律顯示。"
