L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "在角色面板新增一個計算切換按鈕，用來開關升級計算機。"
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "為螢幕中上方的暴雪事件文字與元件（事件階段、活動與首領戰進度條）新增移動錨點。"
