L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "當你獲得新的坐騎／寵物／玩具時，自動關閉「新收藏」的慶祝通知，讓你不必再到收藏圖鑑點選。"
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "每當你開啟拍賣場時，自動啟用「僅限當前資料片」篩選器。"
L["Automatically inserts your key into the Font of Power."] = "自動將你的鑰石插入力量之源。"
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "在開啟或關閉角色面板時，自動開啟和關閉升級計算機。"
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags."] = "背包裡多了袋子、箱子或包裹時，自動幫你打開。"
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "背包裡多了袋子、箱子或包裹時，自動幫你打開。\n\n從信箱收到的容器會保留到你關閉信箱後才開啟，這樣就不會和仍在寄送物品的郵件互相衝突。"
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "當紋章升級 NPC 視窗開啟時，自動開啟升級計算機。"
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "當角色套用外觀變形效果時（如專業裝備、節日服裝、玩具和消耗品），自動予以移除。可透過齒輪圖示精確選擇要移除哪些變形。戰鬥期間套用的變形效果則會在脫離戰鬥後移除。"
L["Automatically repair all gear when visiting a repair vendor."] = "造訪修理商人時自動修理所有裝備。"
L["Automatically sell all junk items when visiting a vendor."] = "造訪商人時自動販賣所有垃圾物品。"
L["Automatically Skip If Possible"] = "若可能則自動略過"
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "進入或離開可記錄的副本時，自動開始和停止戰鬥記錄。"
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "丟棄貴重物品時自動輸入 DELETE。也可以直接按 Enter 確認刪除。"
