L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "隱藏暴雪的「拾取記錄」視窗——也就是持續列出掉落物品、誰擲了什麼、誰得標的清單。也可改用齒輪讓它短暫出現後自動關閉。需求／貪婪的擲骰彈出視窗本身不受影響。"
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "隱藏暴雪的新手教學介面：黃色「說明提示」氣泡，以及法術書、天賦、地圖、收藏等面板上發光的 (i) 說明面板按鈕。"
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "隱藏大多數紅色錯誤訊息（例如「怒氣不足」或「技能尚未就緒」）。重要錯誤（例如背包已滿或任務日誌已滿）仍會顯示。"
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "隱藏截圖後在畫面上出現的「截圖已儲存」通知。"
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "隱藏任務和地城期間出現的大型 NPC 對話彈出視窗。"
L["Hides the loot window movers in Unlock Mode while keeping their saved positions applied."] = "在解鎖模式中隱藏拾取視窗的移動器，但仍保留已套用的儲存位置。"
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "隱藏 Lua 錯誤彈出視窗。與「全域設定 > 開發者」中的設定相同。"
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "在解鎖模式下隱藏頂部列事件文字的移動錨點，同時保留並套用已儲存的位置。"
