L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "僅在地城、團隊本、競技場或戰場中顯示。與「戰鬥」併用即可只在副本戰鬥中顯示。"
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "僅在戰鬥中顯示。與「副本」併用即可只在副本戰鬥中顯示。"
