L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "以「復生」圖示顯示追蹤器，或以精簡的文字列顯示充能次數與距離下一次充能的時間。"
L["Show World MS"]                 = "顯示世界延遲"
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "在所有專精中皆顯示你自己職業的增益，而非僅限於所追蹤的治療者專精。"
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "當小隊或團隊成員死亡時，會在螢幕上顯示大型警報（例如「玩家死亡！」），讓你在地城與團隊副本中立即察覺隊員死亡。使用解鎖模式可重新調整警報位置。"
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "當你進入或離開戰鬥時，在畫面上顯示醒目的大型文字（例如：\"+戰鬥\" / \"-戰鬥\"）。點擊齒輪圖示可設定顯示文字、大小、顏色與觸發時機；切換至解鎖模式則可調整提示的顯示位置。"
L["Shows a popup with party and guild keystones when typing /keys."] = "輸入 /keys 時顯示一個視窗，列出小隊與公會的鑰石。"
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "預設以小圖示顯示，快捷鍵可在圖示與完整視窗之間切換。關閉此選項則直接顯示完整視窗，快捷鍵改為顯示或隱藏視窗。"
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "在傳送按鈕下方顯示「停用功能」文字。關閉時隱藏該文字，視窗高度縮短 20px。"
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "以可移動的文字顯示與當前目標的大約距離（預設為 30-35）。使用齒輪圖示調整格式、對齊方式與字型大小；使用解鎖模式調整位置或錨點定位至玩家框架。"
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "在目前目標的名條上以區間顯示大約距離，例如目標在 15-20 碼時顯示 15+。"
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "顯示已勾選職業的位移技能冷卻倒數。未勾選任何項目＝停用此功能。可使用解鎖模式重新調整位置與大小。"
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "顯示轉化為團隊按鈕，當你已在團隊中時會改顯示為轉化為隊伍。"
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "顯示解散按鈕。解散前一律會先詢問確認，但隱藏它能徹底避免誤觸。"
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "顯示角色類型檢查按鈕。關閉後，其餘按鈕會補上間距。"
