L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "停用右鍵選取目標功能。「敵人」選項適用於所有狀況；「戰鬥中的盟友」選項則僅在戰鬥中限制選取友方目標，以便您在非戰鬥狀態下仍可右鍵點擊商人與 NPC。\n\n注意：啟用此功能時，若游標停在被限制的名條或單位上，按住左右鍵前進將無法運作，因為此功能必須完全接管滑鼠右鍵才能阻擋選取。"
