-- == Blizzard Skin ========================================================
L["\nPick a gem from the list to socket it."] = "\n從清單中挑選一顆寶石進行鑲嵌。"
L["  ... and %d more"]             = "  ... 以及另外 %d 個"
L[" Crests"]                       = "紋章"
L[" to match the EllesmereUI theme."] = " 以符合 EllesmereUI 主題。"
L["%s %.2f%% (%d rating)"]         = "%s %.2f%%（%d 點數）"
L["'s skin requires a UI reload."] = " 的外觀需重新載入介面。"
L["(Against Current Target: %.2f%%)"] = "（對目前目標：%.2f%%）"
L["Above Model"]                   = "模型上方"
L["Accent bar on the active tab of reskinned windows."] = "在美化視窗的目前分頁上顯示裝飾條。"
L["Accent Colored Elements"]       = "強調色元素"
L["Add diminishing-returns detail (adjusted rating, wasted rating, and current penalty bracket) to the Secondary and Tertiary stat tooltips."] = "在次要與特性屬性的滑鼠提示中，增加遞減效應的詳細資訊（調整後數值、浪費的數值及目前的懲罰級距）。"
L["AddOn List"]                    = "插件清單"
L["Adds a glowing, pulsating border around the Accept button of resurrection popups so a pending resurrect is hard to miss. Follows the Element & Text Color setting. Applies instantly, no reload needed."] = "在復活彈出視窗的「接受」按鈕周圍加上發光邊框，讓你絕不漏看復活邀請。顏色會套用「元素與文字顏色」設定。立即生效，無需重新載入介面。"
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "在拾取通知的左側邊緣加上一道對應物品品質顏色的色條。扁平外觀移除了暴雪預設圍繞圖示的品質光條，此選項可將該稀有度提示補回。"
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "新增目標資訊行，顯示滑鼠懸停的玩家或 NPC 當前的目標；若目標是你則顯示為綠色。"
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "於滑鼠提示中顯示玩家當前騎乘的坐騎，並以綠色勾選（已擁有）或紅色叉號（未擁有）標記。"
L["Adjusted Rating: %s"]           = "調整後數值：%s"
L["Agility"]                       = "敏捷"
L["Also show the strip on gold toasts, in the header's gold color. Gold has no rarity to signal, so this is off by default."] = "在金幣通知上也顯示色條，並使用標題的金色。金幣沒有稀有度需要提示，因此預設為關閉。"
L["Appends an item's max stack count on tooltip."] = "在滑鼠提示上顯示物品的最大堆疊數量。"
L["Appends the spell or item ID to tooltips. The same setting as Global Settings > Developer."] = "在提示資訊後附加法術或物品 ID。與全域設定 > Developer 為同一項設定。"
L["Applies EllesmereUI theme styling to the inspect sheet window."] = "將 EllesmereUI 主題樣式套用到檢視面板視窗。"
