L["Reskins Blizzard tooltips with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "將暴雪的滑鼠提示美化為深色、簡約且符合 EUI 風格的樣式。需要重新載入介面才會套用。"
L["Reskins Blizzard's right-click context menus and pop-up dialogs with the EUI dark style. Requires reload to apply."] = "以 EUI 深色風格重新美化暴雪的右鍵選單與彈出對話視窗。需要重新載入介面才會套用。"
L["Reskins the dungeon and battleground queue accept popups with the EUI dark style, and adds an accept countdown timer bar to the dungeon one."] = "以 EUI 深色風格美化地城與戰場的排隊確認彈出視窗，並為地城的視窗加上接受倒數計時條。"
L["Reskins the ESC / Game Menu with the EUI dark style, matching fonts, and accent-colored title."] = "以 EUI 深色風格、相符字型與強調色標題重新美化 ESC／遊戲選單。"
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "將暴雪的螢幕進度條（活動目標、名條計數器）重新美化成 EUI 風格。需要重新載入介面才會套用。\n\n這些條是覆蓋繪製而非直接修改，因此若遊戲將其內容回報為受保護，便會改為顯示原本的進度條。\n\n可用齒輪設定最小大小，讓縮小的名條上的進度條依然清楚易讀。"
