L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "在角色資訊視窗的彈出式裝備清單（滑鼠指向已裝備欄位時，彈出背包中相同部位物品的清單）中，顯示各物品的物品等級，並依品質顏色顯示。"
L["Shows the item level on weapons and armor a vendor sells."] = "顯示商人販售之武器與防具的物品等級。"
