L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "「邀請你加入隊伍」的對話框，包含你的角色職責與接受／拒絕。"
L["The \"You received\" popups for loot, currency, and upgrades."] = "戰利品、貨幣與裝備升級的「你獲得了」彈出通知。"
L["The achievement window: categories, rows, progress bars, and search."] = "成就介面：類別清單、成就項目、進度條與搜尋功能。"
L["The addon manager: list rows, checkboxes, and buttons."] = "插件列表介面：各插件條目、勾選方塊與功能按鈕。"
L["The amount of damage you can take"] = "你能承受的傷害量"
L["The auction house: browse, sell, and my auctions views."] = "拍賣場介面：瀏覽、販售與我的拍賣分頁。"
L["The class and profession trainer window: skill list, train button, and cost display."] = "職業與專業技能訓練師介面：技能列表、學習按鈕與所需費用顯示。"
L["The customer crafting orders window: browse, order form, and my orders."] = "個人製造訂單介面：瀏覽、填寫訂單與我的訂單分頁。"
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "探究難度視窗：階級下拉選單、獎勵清單與「進入」按鈕。「地圖屬性」一列維持原生外觀——那是暴雪的元件顯示，重新美化並不安全。"
L["The gem socketing window with squared gem slots."] = "寶石鑲嵌介面，改用方形寶石欄位。"
L["The Guild & Communities window: roster, chat, and the community list."] = "公會與社群介面：成員名冊、聊天頻道與社群清單。"
L["The housing dashboard window background, border, and title bar."] = "房屋系統介面的背景、邊框與標題列。"
L["The item conversion window (catalyst and similar kiosks)."] = "物品轉換介面（催化劑與類似裝置）。"
L["The item preview / transmog dressing room window."] = "物品預覽／幻化試衣間介面。"
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "物品升級視窗：升級欄位、軌道選擇器、花費與貨幣列。"
L["The loot window: item rows with squared icons, kept item quality colors."] = "拾取視窗：物品列使用方形圖示，並保留物品品質顏色。"
L["The macro editor: tabs, icon grid, text well, and buttons."] = "巨集編輯器：標籤頁、圖示選單、文本輸入框與各項按鈕。"
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "郵箱介面：收件匣清單、寫信、開啟郵件與附件欄位。"
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "月曆主畫面、事件設定視窗以及月份切換箭頭。"
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "需求／貪婪／放棄的擲骰彈出視窗，改用方形圖示與扁平風格的擲骰計時條。"
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "NPC 對話介面：問候文字、閒聊與任務選項，以及結束對話按鈕。"
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "NPC 任務介面：任務內容、進度與獎勵面板，以及多任務選單列表。"
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "將滑鼠移至小地圖的隊伍搜尋器眼睛圖示時顯示的面板：排隊標題、角色職責圖示與人數，以及排隊時間。"
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "待決擲骰的視窗：首領選擇器、擲骰計時與結果列。"
L["The Player Spells window: talents, spec selection, and the spellbook."] = "玩家法術介面：天賦、專精選擇與法術書。"
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "玩家之間的交易視窗：框架、雙方的物品欄、附魔格、金錢列與按鈕。物品圖示改為方形並帶有稀有度邊框。兩側頭像皆已移除，與其他視窗一致。"
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "專業技能製作介面：配方清單、成品預覽、專精與製造訂單。"
L["The professions overview book with squared icons and flat progress bars."] = "專業技能總覽介面，改用方形圖示與扁平風格進度條。"
L["The ready check prompt with its Yes / No buttons."] = "準備確認提示與其「是」／「否」按鈕。"
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "檢視他人連結配方或工匠專業時的配方預覽介面。"
L["The size of your mana pool"]    = "你的法力值上限"
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "社交介面的框架、邊框、標題列、戰網列、搜尋框、篩選下拉選單與按鈕。清單內容與側邊分頁圖示不受影響。"
