L["Show copies of the same item that sit in separate bag slots as one icon with their counts added together. Turn this off to keep every slot separate, for example when you deliberately split stacks. Merging is always paused while the mail, trade, auction house, bank or guild bank window is open, since those take one bag slot at a time."] = "將分散在不同背包欄位的相同物品合併顯示為一個圖示，並將數量加總。關閉此選項可讓每個欄位維持獨立顯示，例如你刻意分割堆疊時。當郵件、交易、拍賣場、銀行或公會銀行視窗開啟時，合併功能會自動暫停，因為這些介面一次只會佔用一個背包欄位。"
