L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "一般排序會將物品收攏至最前面的空欄位，也就是靠在格線頂端。開啟此選項後，改為收攏至最後面的欄位，使空欄位留在頂端。物品本身的排列順序不會改變。此設定會影響「單一背包」、「多重背包」與銀行檢視——分類檢視會填滿自身的格線而不留空隙，因此無需移動。多重背包與銀行採用暴雪原生的排序，因此開啟時也會一併反轉暴雪「整理背包」的方向；關閉後即可恢復原本的方向。"
