L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "隱藏此角色無法使用的項目：其他職業的專精與法術，以及此角色沒有的巨集。這樣一份共用選單就能適用於每個角色。選單編輯器則一律顯示所有項目。"
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire."] = "按住快捷鍵開啟動作選單；以游標指向或滾動來選擇，放開即施放。"
L["How far along the arc a nest may spread its entries."] = "巢狀選單項目沿著弧形展開的範圍。"
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "巢狀選單項目沿著弧形展開的範圍。「限制範圍」會與左右兩側的下一個巢狀選單保持距離，確保兩者絕不重疊繪製；「允許溢出」則允許使用整個「巢狀選單最大跨度」。巢狀選單會跨越其經過的一般項目，且這些項目僅在該巢狀選單開啟時才會讓出自身的角度。"
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "格狀的一列可容納幾個項目。設為 1 會把它們疊成單一欄；設為 %1$s（動作選單可容納的最大格數）則會排成單一列。"
