L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "這會覆蓋此動作選單目前的設定。它的動作、名稱與快捷鍵不會變更。"
L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "為目前按下去不會有任何效果的項目上色：目標超出距離時為紅色、資源不足時為藍色、遊戲因其他原因拒絕時為灰色。僅適用於法術與物品——遊戲會把所有玩具都回報為無法使用，而巨集能否使用取決於其內容實際解析成什麼。"
L["Toggle World Markers"] = "切換世界標記"
