L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "再次使用世界標記項目即可把該標記收回。關閉時則會在新位置再放置一次標記。\n這不會影響用來清除所有世界標記的項目，也不影響循環切換的項目。"
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "在以「切換選單開啟」保持選單開啟時，使用你目前指向的項目。所有選單共用同一個按鍵，且僅在選單開啟期間被佔用——滑鼠按鍵在其餘時間仍維持原本的用途。"
