-- == Core / General =======================================================
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "「%1$s」已儲存，但由於此專精已指定了其他設定檔，因此無法載入。"
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile. Switch specs or remove the spec assignment to use it."] = "「%1$s」已儲存，但由於此專精已指定了其他設定檔，因此無法載入。請切換專精或移除該專精的設定檔指定來使用它。"
