L["%s Override Active"]            = "%s 覆寫啟用中"
L["'%s' is now customized for %s."] = "「%s」現在已為 %s 自訂。"
L["(Applies on Window Close)"]     = "關閉視窗時套用"
L["(Spec prio'd for settings conflicts)"] = "（設定衝突時以專精優先）"
L["*Blizzard's auto targeting (soft target) setting can cause brief flickering when your actual target dies but a soft-target is still active."] = "*啟用暴雪的「自動選取目標」（軟目標）時，若實際目標死亡而軟目標依然作用中，可能會導致介面短暫閃爍。"
L["*Please enter a profile name"]  = "*請輸入設定檔名稱"
L["+ Add New Conditional Group"]   = "＋ 新增條件群組"
L["+ Add New Spec Group"]          = "＋ 新增專精群組"
L["+1 Threshold Text Size"]        = "+1 門檻文字大小"
L["+2 Threshold Text Size"]        = "+2 門檻文字大小"
L["+3 Threshold Text Size"]        = "+3 門檻文字大小"
L["A CDM replacement focused on performance, customizations and alerts."] = "專注於效能、自訂與警示的冷卻管理器替代方案。"
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "為暴雪任務追蹤帶來俐落的更新換膚。"
L["A modern friends list with built-in organization tools."] = "內建整理工具的現代化好友列表。"
L["A new age minimap with clean styling and square layout options."] = "具備俐落風格與方形版面選項的新世代小地圖。"
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "已存在名為「%1$s」的設定檔。請選擇其他名稱。"
L["A quick view of every font setting in one place."] = "在同一處快速檢視所有字型設定。"
L["A quick view of every texture setting in one place."] = "在同一處快速檢視所有材質設定。"
L["A simple Mythic+ timer with full tracking customizations."] = "可完整自訂追蹤的簡易傳奇+計時器。"
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "此設定已被某個專精覆寫持有，因此這個條件值在編輯模式之外永遠不會套用。請移除該專精覆寫，才能讓它生效。"
L["A sync group needs at least two profiles"] = "同步群組至少需要兩個設定檔"
