L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "設定套用於所有 EllesmereUI 元素（分頁、發光、高亮、邊框）的強調色。預設為你的佈景主題顏色。"
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "設定世界中浮動於玩家、NPC 與敵人上方的名稱字型。\n\n與「全域字型」各自獨立：變更此項不會影響介面的其他部分，「全域字型」也不會影響它。\n\n選擇「暴雪預設」則完全不改動名稱文字。\n\n|cffff4d4d需要重新登入或重新啟動 WoW 才會生效。|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "設定整個遊戲介面的縮放。數值越低所有元素越小，數值越高所有元素越大。"
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "將 UI 縮放設為其他插件使用的精確像素完美值。EllesmereUI 並不要求像素完美。"
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "「設定覆寫」是 EllesmereUI 最強大、也最深入的系統。花幾分鐘看完這支影片，可以省下你自己摸索的好幾個小時。"
