L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "「解鎖模式」是你在 EllesmereUI 中移動所有元素、調整其大小的方式，而且工具非常齊全：錨點、寬度對齊、備用錨點、各群組專屬的版面配置。這支影片能讓你很快上手。"
