-- Search Keywords: the haystack behind the sidebar "Search Features..." box,
-- NOT display text -- nothing in the section below is ever drawn on screen.
-- EllesmereUI.lua `_applySidebarSearch` -> addLocalized() indexes the English
-- form AND the translated form of every module's `searchTerms`, so these
-- entries ADD Chinese search words without taking the English ones away: both
-- still match. The query is split on whitespace and every word must be a
-- plain substring of the joined haystack.
--
-- Translate as SEARCH WORDS, not as prose: whatever a zhTW player would
-- actually type. New keys come from the 7 `searchTerms =` sites in
-- EllesmereUIOptions/ -- apply.py appends them after the last entry below, so
-- move them into the right sub-block by hand.
-- == Search Keywords =======================================================

-- Whole-module keyword blobs. The English side is one long space-separated
-- string per module (`searchTerms = "bags inventory items ..."`), so the
-- translation is one too.
L["bags inventory items slots reagent categories columns sidebar"] = "背包 包包 物品 格子 材料 分類 欄數 側邊欄"
L["blizzard skin character sheet tooltip menu popup dragon riding skyriding window skins lfg group finder premade queue pause game menu great vault inspect collections mounts pets toys spellbook talents adventure guide encounter journal professions guild communities calendar achievements mail catalyst gem socket item upgrade upgrades crest loot window loot toast you received popup micro menu modern delves companion brann loot roll need greed pass disenchant loot rolls pending rolls group invite invited to a group role"] = "暴雪 換膚 美化 角色面板 提示資訊 選單 彈出視窗 騎龍 飛龍騎術 視窗換膚 組隊搜尋器 預組隊伍 排隊 暫停 遊戲選單 寶庫 觀察 收藏 坐騎 寵物 玩具 法術書 天賦 冒險指南 首領戰術 專業技能 公會 社群 行事曆 成就 郵件 催化劑 寶石 插槽 物品升級 紋章 拾取視窗 拾取通知 你獲得了 微型選單 探究 探究夥伴 布萊恩 拾取擲骰 需求 貪婪 放棄 分解 拾取記錄 待處理擲骰 隊伍邀請 邀請你加入隊伍 職責"
L["chat tabs border spacing background sidebar friends voice url copy whisper channel abbreviate shortened class color names timestamps timestamp all messages font size"] = "聊天 頁籤 分頁 邊框 間距 背景 側邊欄 好友 語音 網址 連結 複製 密語 頻道 縮寫 縮短 職業配色 名稱 時間戳記 所有訊息加上時間戳記 字型 字體大小"
